#include <iostream>
#include <string>
#include <cstdlib>

static std::string add_dec(const std::string& a, const std::string& b) {
    std::string out;
    out.reserve((a.size() > b.size() ? a.size() : b.size()) + 1);
    int ai = (int)a.size() - 1;
    int bi = (int)b.size() - 1;
    int carry = 0;
    while (ai >= 0 || bi >= 0 || carry) {
        int sum = carry;
        if (ai >= 0) sum += a[ai--] - '0';
        if (bi >= 0) sum += b[bi--] - '0';
        out.push_back((char)('0' + (sum % 10)));
        carry = sum / 10;
    }
    for (int i = 0, j = (int)out.size() - 1; i < j; ++i, --j) {
        char t = out[i]; out[i] = out[j]; out[j] = t;
    }
    return out;
}

static std::string fib(int n) {
    if (n <= 1) return "1";
    std::string a = "1";
    std::string b = "1";
    for (int i = 2; i <= n; ++i) {
        std::string c = add_dec(a, b);
        a = b;
        b = c;
    }
    return b;
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    int n = std::atoi(argv[1]);
    std::cout << fib(n) << std::endl;
    return 0;
}
