    let ab = a.as_bytes();
    let bb = b.as_bytes();
    let mut ai = ab.len() as isize - 1;
    let mut bi = bb.len() as isize - 1;
    let mut carry: u32 = 0;
    let mut out: Vec<u8> = Vec::new();
    while ai >= 0 || bi >= 0 || carry > 0 {
        let mut sum = carry;
        if ai >= 0 {
            sum += (ab[ai as usize] - b'0') as u32;
            ai -= 1;
        }
        if bi >= 0 {
            sum += (bb[bi as usize] - b'0') as u32;
            bi -= 1;
        }
        out.push(b'0' + (sum % 10) as u8);
        carry = sum / 10;
    }
    out.reverse();
    String::from_utf8(out).unwrap()
}

fn fib(n: u32) -> String {
    if n <= 1 {
        return String::from("1");
    }
    let mut a = String::from("1");
    let mut b = String::from("1");
    for _ in 2..=n {
        let c = add_dec(&a, &b);
        a = b;
        b = c;
    }
    b
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return;
    }
    let n: u32 = args[1].parse().unwrap();
    println!("{}", fib(n));
}
